using System.Diagnostics;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace MiddlewareDemo;

// 基于类的中间件：请求日志
class RequestLoggingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<RequestLoggingMiddleware> _logger;

    public RequestLoggingMiddleware(RequestDelegate next, ILogger<RequestLoggingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var sw = Stopwatch.StartNew();
        _logger.LogInformation("{Method} {Path} started", context.Request.Method, context.Request.Path);

        await _next(context); // 调用下游

        sw.Stop();
        _logger.LogInformation("{Method} {Path} finished {StatusCode} in {Elapsed}ms",
            context.Request.Method, context.Request.Path,
            context.Response.StatusCode, sw.ElapsedMilliseconds);
    }
}

// 基于类的中间件：慢请求告警
class SlowRequestWarningMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<SlowRequestWarningMiddleware> _logger;
    private readonly int _thresholdMs;

    public SlowRequestWarningMiddleware(RequestDelegate next, ILogger<SlowRequestWarningMiddleware> logger, int thresholdMs = 1000)
    {
        _next = next;
        _logger = logger;
        _thresholdMs = thresholdMs;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var sw = Stopwatch.StartNew();
        await _next(context);
        sw.Stop();
        if (sw.ElapsedMilliseconds > _thresholdMs)
        {
            _logger.LogWarning("Slow request: {Path} took {Elapsed}ms", context.Request.Path, sw.ElapsedMilliseconds);
        }
    }
}

// 基于类的中间件扩展方法
static class MiddlewareExtensions
{
    public static IApplicationBuilder UseRequestLogging(this IApplicationBuilder app)
        => app.UseMiddleware<RequestLoggingMiddleware>();

    public static IApplicationBuilder UseSlowRequestWarning(this IApplicationBuilder app, int thresholdMs = 1000)
        => app.UseMiddleware<SlowRequestWarningMiddleware>(thresholdMs);
}

// 入口
var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// 最外层：异常处理
app.UseExceptionHandler("/error");

// 日志：捕获所有请求及响应状态
app.UseRequestLogging();

// 内联中间件：健康检查短路
app.Use(async (context, next) =>
{
    if (context.Request.Path == "/health")
    {
        context.Response.ContentType = "text/plain";
        await context.Response.WriteAsync("OK");
        return; // 短路：不调 next，后续中间件不执行
    }
    await next();
});

// 慢请求告警
app.UseSlowRequestWarning(500);

// Map 分支：/api 子管道
app.Map("/api", apiApp =>
{
    apiApp.Use(async (context, next) =>
    {
        context.Response.Headers["X-Api-Version"] = "1.0";
        await next();
    });
    apiApp.Run(async context =>
    {
        await context.Response.WriteAsync("API response from branched pipeline");
    });
});

// 终端中间件
app.Run(async context =>
{
    context.Response.StatusCode = 200;
    await context.Response.WriteAsync("Hello from terminal middleware");
});

app.Run();
